INSERT INTO productos (codigo, titulo, descripcion, descripcion_larga, especificaciones, precio, categoria, imagen) VALUES
('GA001', 'Yamaha F310', 'Guitarra Acústica Folk. Tapa de abeto, aros y fondo de meranti.', 'La Yamaha F310 ofrece una calidad extraordinaria a un precio realmente asequible. Su sonido vivo y cálido proviene de una tapa de abeto seleccionada y aros/fondo de meranti. Su cuerpo de tamaño tradicional Dreadnought y su escala ligeramente reducida garantizan una excelente comodidad al tocar.', 'Tapa: Abeto macizo||Aros y Fondo: Meranti||Mástil: Nato / Caoba||Diapasón: Palo de rosa (Rosewood)||Número de Trastes: 20||Escala: 634 mm (25")||Acabado: Brillante natural', 129990, 'Guitarras Acústicas', '/imagenes/productos/GA001.jpg'),
('GA002', 'Fender CD-60S', 'Guitarra Acústica Dreadnought. Tapa de abeto macizo, brazo de caoba.', 'La CD-60S es uno de los modelos más populares de Fender, ideal para músicos que buscan una guitarra acústica con gran resonancia y proyección. Cuenta con tapa de abeto macizo, bordes del diapasón enrollados para máxima comodidad y aros/fondo de caoba.', 'Forma del Cuerpo: Dreadnought||Tapa: Abeto Macizo||Aros y Fondo: Caoba||Mástil: Caoba con perfil ''Easy-to-Play''||Diapasón: Nogal con bordes redondeados||Trastes: 20 Vintage||Clavijero: Chrome Die-Cast', 189990, 'Guitarras Acústicas', '/imagenes/productos/GA002.jpg'),
('GA003', 'Yamaha C40', 'Guitarra Acústica Clásica 4/4. Nailon, tapa de abeto.', 'Un estándar de la industria para estudiantes y conservatorios. La Yamaha C40 ofrece un tono clásico excepcionalmente equilibrado gracias a sus cuerdas de nylon de alta calidad y la combinación de madera de abeto en la tapa y meranti en el cuerpo.', 'Tipo: Guitarra Clásica Española 4/4||Tapa: Abeto||Aros y Fondo: Meranti||Mástil: Nato||Diapasón: Palo de rosa||Cuerdas: Nylon de tensión media||Ancho de cejuela: 52 mm', 89990, 'Guitarras Acústicas', '/imagenes/productos/GA003.jpg'),
('GA004', 'Takamine GN20CE', 'Guitarra Electroacústica. Pickup integrado, afinador incorporado.', 'Con la elegante forma del cuerpo NEX propia de Takamine, esta electroacústica combina una tapa de cedro macizo con aros y fondo de caoba para producir un tono cálido y detallado. Incluye el preamplificador Takamine TP-4TD con afinador integrado.', 'Cuerpo: NEX Cutaway||Tapa: Cedro Macizo||Aros y Fondo: Caoba||Electrónica: Preamplificador Takamine TP-4TD con ecualizador de 3 bandas||Afinador: Integrado con pantalla digital||Puente: Pin-less de palisandro', 349990, 'Guitarras Acústicas', '/imagenes/productos/GA004.jpg'),
('GA005', 'Yamaha JR1', 'Guitarra 3/4 Niños. Tamaño reducido para niños de 6 a 10 años.', 'Diseñada a imagen y semejanza de la famosa serie FG de Yamaha, la JR1 es una guitarra compacta de escala 3/4 perfecta para niños pequeños o como guitarra de viaje súper portátil sin sacrificar tono ni afinación.', 'Escala: 3/4 (540 mm)||Tapa: Abeto||Aros y Fondo: Meranti||Mástil: Nato||Diapasón: Palo de rosa||Incluye: Funda acolchada original Yamaha', 79990, 'Guitarras Acústicas', '/imagenes/productos/GA005.jpg'),
('GE001', 'Squier Affinity Strat', 'Guitarra Eléctrica Stratocaster. Cuerpo de álamo, mástil de arce.', 'La Squier Affinity Series Stratocaster ofrece un diseño legendario y el tono definitivo de Fender. Con un cuerpo liviano de álamo, perfil de mástil en ''C'' muy cómodo y tres cápsulas Single-Coil que entregan el sonido clásico e inconfundible de la Strat.', 'Cuerpo: Álamo||Mástil: Arce (Maple) atornillado||Perfil del mástil: ''C'' delgado||Cápsulas: 3 x Ceramic Single-Coil||Controles: Volumen master, Tono 1, Tono 2, Selector de 5 posiciones||Puente: Trémolo sincronizado de 2 puntos', 249990, 'Guitarras Eléctricas', '/imagenes/productos/GE001.jpg'),
('GE002', 'Epiphone Les Paul Std', 'Guitarra Eléctrica Les Paul. Cuerpo caoba, tapa arce.', 'La Epiphone Les Paul Standard recrea fielmente el modelo clásico de los años 50. Equipada con un cuerpo de caoba maciza, tapa de arce figurado y un par de potentes pastillas Humbucker Alnico Classic PRO para un sustain infinito.', 'Cuerpo: Caoba||Tapa: Arce figurado||Mástil: Caoba encolado (Set-neck)||Perfil: SlimTaper 60s C||Cápsulas: Epiphone Alnico Classic PRO Humbuckers||Puente: LockTone Tune-O-Matic con Stopbar', 329990, 'Guitarras Eléctricas', '/imagenes/productos/GE002.jpg'),
('GE003', 'Epiphone SG Standard', 'Guitarra Eléctrica SG. Cuerpo caoba, mástil caoba, 2 humbuckers.', 'La Epiphone SG Standard de la colección ''Inspired by Gibson'' recrea la legendaria guitarra de doble cutaway que definió el rock pesado y el hard rock en los 60. Ligera, rápida y extremadamente agresiva.', 'Cuerpo: Caoba maciza||Mástil: Caoba encolado||Escala: 24.75"||Cápsulas: Alnico Classic PRO||Clavijero: Epiphone Deluxe con botones de tulipán||Electrónica: Potenciómetros CTS', 319990, 'Guitarras Eléctricas', '/imagenes/productos/GE003.jpg'),
('GE004', 'Squier Affinity Tele', 'Guitarra Eléctrica Telecaster. Cuerpo álamo, clavijero vintage.', 'La clásica Telecaster adaptada para los músicos de hoy. Destaca por su twang característico, cápsulas de cerámica monobobina y su cuerpo ultra cómodo con puente Through-Body para mayor resonancia.', 'Cuerpo: Álamo||Mástil: Arce||Cápsulas: 2 x Ceramic Single-Coil Tele||Puente: 6-Saddle String-Through-Body Tele||Controles: Master Volume, Master Tone, Selector de 3 vías', 239990, 'Guitarras Eléctricas', '/imagenes/productos/GE004.jpg'),
('GE005', 'Epiphone ES-335', 'Guitarra Eléctrica Semi-hollow. Semi-hueca, ideal para jazz y blues.', 'La Epiphone ES-335 es la versión accesible de la histórica guitarra semihueca. Presenta un bloque central de arce para evitar el acople (feedback), tapa de arce laminado y pastillas Alnico Classic PRO de tono suave y esponjoso.', 'Cuerpo: Arce laminado Semi-Hollow con bloque central de arce||Mástil: Caoba||Cápsulas: Alnico Classic PRO Humbuckers||Nut: Graph Tech NuBone||Trastes: 22 Medium Jumbo', 549990, 'Guitarras Eléctricas', '/imagenes/productos/GE005.jpg'),
('BA001', 'Squier Affinity PJ', 'Bajo Eléctrico 4 Cuerdas. Pickup PJ, cuerpo álamo, mástil arce.', 'El Squier Affinity Series Precision Bass PJ combina el estruendoso golpe de la cápsula de mástil P-Bass con el tono punzante de la cápsula de puente J-Bass, entregando una versatilidad tonal idónea para cualquier género.', 'Configuración de Cápsulas: PJ (Precision / Jazz)||Cuerpo: Álamo||Mástil: Arce||Perfil del Mástil: ''C'' delgado y cómodo||Controles: 2 Volúmenes independientes, 1 Tono Master', 299990, 'Bajos', '/imagenes/productos/BA001.jpg'),
('BA002', 'Fender Player Jazz', 'Bajo Eléctrico Jazz Bass. Alder body, 2 Alnico V Jazz single-coil.', 'Con sus dos pastillas de bobina simple y su tacto suave, el Player Jazz Bass es un instrumento inspirador con un estilo clásico y auténtico tono de bajo Fender. Sonido potente, nítido y con gran pegada.', 'Cuerpo: Aliso (Alder)||Mástil: Arce perfil ''Modern C''||Diapasón: Arce o Pau Ferro con radio de 9.5"||Cápsulas: 2 x Player Series Alnico 5 Single-Coil Jazz Bass||Puente: Estándar de 4 selletas', 699990, 'Bajos', '/imagenes/productos/BA002.jpg'),
('BA003', 'Yamaha APX700II', 'Bajo Acústico 4 Cuerdas. Electroacústico, afinador incorporado.', 'Bajo electroacústico de escala completa y cuerpo delgado. Diseñado para ofrecer una comodidad superior en el escenario y un tono acústico orgánico gracias a su sistema de pastillas piezoeléctricas de alta precisión.', 'Tapa: Abeto Macizo||Aros y Fondo: Nato||Electrónica: System 64 con afinador y ecualizador de 3 bandas||Escala: 34" (Long Scale)||Diapasón: Palo de rosa', 429990, 'Bajos', '/imagenes/productos/BA003.jpg'),
('BT001', 'Pearl Roadshow', 'Batería Acústica 5 piezas. Incluye stands, platillos y pedal.', 'El kit perfecto para empezar a tocar inmediatamente. Incluye cascos de álamo de 9 capas (7mm), herrajes de doble pata ultra resistentes, platillos de ensayo, sillín y banquetas.', 'Configuración: Bombo 22", Toms 10" y 12", Floor Tom 16", Caja 14"||Material: Álamo de 9 capas (7mm)||Platillos Incluidos: Hi-Hat 14" y Crash/Ride 16"||Herrajes: Soportes de doble perfil, pedal de bombo y sillín incluidos', 599990, 'Baterías', '/imagenes/productos/BT001.jpg'),
('BT002', 'Roland TD-02KV', 'Batería Electrónica 8 pads. Módulo TD-02, 8 pads de goma.', 'La serie TD-02 te ofrece la experiencia de batería electrónica de nivel de entrada superior del mundo a un precio asequible. Impulsada por décadas de innovación V-Drums con pads de caja de malla súper silenciosos.', 'Módulo: TD-02 con 16 kits listos para tocar||Pad de Caja: Malla PDX-8 de doble zona||Conectividad: Salida de audífonos, entrada Mix In, USB MIDI||Funciones de Práctica: 5 funciones de Coach integradas', 799990, 'Baterías', '/imagenes/productos/BT002.jpg'),
('BT003', 'Pearl STE1450', 'Caja Snare 14". Acero, 14x5", 10 tensores.', 'Redoblante de acero inoxidable de 14x5 pulgadas con un sonido cortante, brillante y seco. Excelente para atravesar mezclas en vivo tanto en rock, pop como en funk.', 'Medidas: 14" x 5"||Material: Acero cromado (1.0mm)||Tensores: 10 por lado||Aros: 1.6mm Steel Hoops', 89990, 'Baterías', '/imagenes/productos/BT003.jpg'),
('BT004', 'Zildjian A Series 14"', 'Platillo Hi-Hat 14". Latón B20, sonido brillante y claro.', 'Los platillos Zildjian A-Custom Hi-Hats de 14 pulgadas ofrecen un sonido moderno, sofisticado y brillante pero nunca demasiado estridente. Respuesta táctil limpia y definición del baqueteo insuperable.', 'Serie: A Custom||Tipo: Hi-Hat (Pareja)||Tamaño: 14 pulgadas||Aleación: Bronce Zildjian B20 secret alloy||Acabado: Brillante', 149990, 'Baterías', '/imagenes/productos/BT004.jpg'),
('BT005', 'Zildjian A Series 16"', 'Platillo Crash 16". Latón B20, ataque rápido.', 'Un clásico atemporal. Este crash de 16 pulgadas responde al instante con un ataque veloz y un decay medio perfecto para cualquier acento musical rítmico.', 'Serie: A Custom||Tipo: Crash||Tamaño: 16 pulgadas||Aleación: Bronce B20||Sonido: Brillante / Medio colapso', 129990, 'Baterías', '/imagenes/productos/BT005.jpg'),
('TC001', 'Yamaha PSR-E373', 'Teclado Digital 61 teclas. Sensible a la velocidad, 622 voces.', 'Un teclado portátil dinámico para principiantes y entusiastas. Equipado con una sensibilidad al tacto superior y el generador de tonos LSI de Yamaha que ofrece un repertorio gigante de voces de instrumentos.', 'Teclas: 61 sensibles al tacto||Polifonía: 48 notas||Voces: 622 sonidos de alta calidad||Efectos: DSP, Reverb, Chorus, Master EQ||Lecciones: Sistema de aprendizaje ''Keys to Success''', 249990, 'Teclados', '/imagenes/productos/TC001.jpg'),
('TC002', 'Yamaha P-45', 'Piano Digital 88 teclas. Mecanismo Graded Hammer Standard.', 'El piano digital con contrapeso de 88 teclas más cotizado del mercado. Utiliza la tecnología GHS (Graded Hammer Standard) de Yamaha para simular el peso de los martillos de un piano acústico de cola.', 'Teclas: 88 teclas contrapesadas (GHS)||Muestra de sonido: AWM Stereo Sampling||Polifonía: 64 notas||Conexiones: USB to Host, salida de auriculares, entrada de pedal Sustain||Incluye: Pedal de sustain y atril de partituras', 499990, 'Teclados', '/imagenes/productos/TC002.jpg'),
('TC003', 'Arturia MiniLab MKII', 'Sintetizador 49 teclas. Teclas delgadas, 8 pads RGB.', 'Un controlador MIDI portátil versátil que combina teclas de formato slim sensibles a la velocidad, pads retroiluminados RGB y potenciómetros giratorios para un control total de tu Software DAW.', 'Teclas: 25 teclas delgadas sensibles a la velocidad||Pads: 8 pads retroiluminados RGB ultra sensibles||Encoders: 16 potenciómetros giratorios||Software incluido: Analog Lab Lite, Ableton Live Lite, Grand Piano Model D', 129990, 'Teclados', '/imagenes/productos/TC003.jpg'),
('TC004', 'M-Audio Hammer 88', 'Teclado MIDI 88 teclas. Teclas contrapesadas de acción martillo.', 'Controlador USB/MIDI premium para pianistas que buscan la sensación real de un piano de cola combinada con el flujo de trabajo del estudio digital moderno.', 'Teclas: 88 teclas contrapesadas con acción martillo||Controles: Ruedas de Pitch Bend y Modulación, fader de volumen master||Entradas de pedal: Sustain, Expression y Soft||Alimentación: Vía USB o adaptador de corriente', 399990, 'Teclados', '/imagenes/productos/TC004.jpg'),
('AM001', 'Fender Frontman 15G', 'Amplificador Guitarra 15W. 2 canales, ecualizador de 3 bandas.', 'Amplificador de práctica ideal con el tono limpio característico de Fender y un circuito de overdrive seleccionable para riffs distorsionados con mucho cuerpo.', 'Potencia: 15 Watts RMS||Altavoz: 1 x 8" Fender Special Design||Canales: 2 (Normal y Drive)||Ecualización: Treble, Middle, Bass||Salida: Auriculares con emulación de gabinete', 99990, 'Amplificadores', '/imagenes/productos/AM001.jpg'),
('AM002', 'Marshall MG40GFX', 'Amplificador Guitarra 40W. Efectos digitales integrados.', 'Potente amplificador para ensayo y directo con el icónico tono Marshall. Incluye 4 canales programables y una suite completa de efectos digitales (Reverb, Delay, Chorus, Flanger, Phaser).', 'Potencia: 40 Watts RMS||Altavoz: 1 x 10" personalizado||Canales: Clean, Crunch, OD1, OD2||Efectos: Reverb de estudio, Chorus, Phaser, Flanger, Delay analógico/digital', 299990, 'Amplificadores', '/imagenes/productos/AM002.jpg'),
('AM003', 'Hartke HD100', 'Amplificador Bajo 100W. Altavoz HyDrive de 15 pulgadas.', 'Equipado con la galardonada tecnología de altavoces HyDrive de Hartke (cono híbrido de aluminio y papel). Proporciona bajos profundos y punch contundente en frecuencias medias.', 'Potencia: 100 Watts||Altavoz: 15" HyDrive con imán de neodimio||Ecualizador: Gráfico de 7 bandas||Limitador: Circuito de protección integrado', 449990, 'Amplificadores', '/imagenes/productos/AM003.jpg'),
('AM004', 'Fishman Loudbox Mini', 'Amplificador Acústico 40W. Micrófono y guitarra, Bluetooth.', 'El estándar de la industria para amplificación de instrumentos acústicos. Ofrece 40 vatios de potencia transparente con dos canales independientes para guitarra e instrumento vocal con conectividad Bluetooth.', 'Potencia: 40 Watts con Master Volume||Canales: Canal 1 para instrumento (jack 1/4"), Canal 2 para micrófono (XLR)||Efectos: Digital Reverb y Chorus||Conectividad: Bluetooth 4.0 y salida D.I. XLR balanceada', 499990, 'Amplificadores', '/imagenes/productos/AM004.jpg'),
('MI001', 'Shure SM58', 'Micrófono Dinámico Cardioide. Patrón polar cardioide.', 'El micrófono vocal más famoso y legendario del planeta. Diseñado para actuaciones en vivo, el SM58 aísla la voz principal y elimina el ruido ambiental de fondo gracias a su filtro esférico integrado.', 'Tipo: Dinámico||Patrón Polar: Cardioide||Respuesta de frecuencia: 50 a 15,000 Hz||Estructura: Metal indestructible a prueba de golpes', 149990, 'Micrófonos', '/imagenes/productos/MI001.jpg'),
('MI002', 'Shure SM57', 'Micrófono Dinámico Instrumento. Respuesta para instrumentos.', 'Insuperable para la microfonía de tambores, cajas de batería, amplificadores de guitarra eléctrica e instrumentos de viento. Soporta altos niveles de presión sonora SPL sin distorsionar.', 'Tipo: Dinámico||Patrón Polar: Cardioide||Uso Recomendado: Redoblantes, amplificadores de guitarra y metales||Conector: XLR de 3 pines', 139990, 'Micrófonos', '/imagenes/productos/MI002.jpg'),
('MI003', 'Audio-Tech. AT2020', 'Micrófono Condensador de estudio.', 'Micrófono de condensador de diafragma grande ideal para home studios. Ofrece un rango dinámico excepcionalmente amplio y capacidad para manejar altos niveles de SPL con total claridad.', 'Elemento: Condensador con placa trasera de carga fija||Patrón Polar: Cardioide||Respuesta en Frecuencia: 20-20,000 Hz||Requiere: Phantom Power +48V', 199990, 'Micrófonos', '/imagenes/productos/MI003.jpg'),
('MI004', 'Blue Yeti', 'Micrófono USB de Condensador. Múltiples patrones polares.', 'El micrófono USB número uno para podcasters, streamers y creadores de contenido. Presenta un arreglo exclusivo de 3 cápsulas con 4 patrones de captación seleccionables (Estéreo, Cardioide, Omnidireccional, Bidireccional).', 'Conexión: USB Plug and Play||Patrones Polares: Cardioide, Bidireccional, Omnidireccional, Estéreo||Salida de Audífonos: 3.5mm con latencia cero||Controles: Ganancia, Mute, Volumen de auricular', 299990, 'Micrófonos', '/imagenes/productos/MI004.jpg'),
('PE001', 'Boss DS-1', 'Pedal Distorsión analógica clásica para guitarra.', 'El pedal de distorsión más vendido de la historia de BOSS. Proporciona un tono de distorsión cortante para guitarra y teclados, reproduciendo fielmente todos los matices de tu interpretación.', 'Circuito: Analógico||Controles: Tone, Level, Distortion||Alimentación: Batería de 9V o adaptador de corriente DC 9V||Carcasa: Metal ultra resistente BOSS', 79990, 'Pedales', '/imagenes/productos/PE001.jpg'),
('PE002', 'Boss RV-6', 'Pedal Reverb. Procesamiento DSP con 8 modos.', 'Combinando sonido de alta definición y versatilidad de vanguardia, el RV-6 pone la reverberación de estudio en un formato compacto. Modos que van desde salas clásicas hasta sonidos modernos Shimmer.', 'Modos: Hall, Plate, Room, Spring, Modulate, Dynamic, Shimmer, Delay||Entradas/Salidas: Estéreo completas||Procesamiento: DSP avanzado BOSS de 32 bits', 179990, 'Pedales', '/imagenes/productos/PE002.jpg'),
('PE003', 'Boss ME-80', 'Pedal Multi-efectos. Simulación de amplificadores COSM.', 'Procesador de guitarra multiefectos impulsado por footswitches de acceso directo. Ofrece modelado de amplificadores COSM derivados de la pedalera flagship GT-100.', 'Efectos: Overdrive, Delay, Reverb, Modulación, Wah, Compresor||Pedal de Expresión: Integrado||Interfaz de Audio: USB integrada para grabación direct-to-DAW', 349990, 'Pedales', '/imagenes/productos/PE003.jpg'),
('PE004', 'Boss TU-3', 'Pedal Tuner Cromático ultra preciso.', 'El afinador de escenario estándar de la industria en formato pedal. Cuenta con un medidor LED de 21 segmentos con un modo de alto brillo para visibilidad óptima bajo la luz del sol al aire libre.', 'Rango de afinación: C0 (16.35Hz) a C8 (4,186Hz)||Precisión: +/- 1 centésima||Pantalla: LED de 21 segmentos con modo High Brightness', 89990, 'Pedales', '/imagenes/productos/PE004.jpg'),
('PE005', 'MXR Carbon Copy', 'Pedal Delay analógico con circuito BBD.', 'Pedal de delay 100% analógico impulsado por tecnología de brigada de cubos (Bucket-Brigade). Entrega repeticiones cálidas y orgánicas con hasta 600ms de tiempo de retardo.', 'Tecnología: Analógica BBD||Tiempo de Delay: De 20ms a 600ms||Switch de Modulación: Añade vibrato/chorus a las repeticiones||Bypass: True Hardwire Bypass', 179990, 'Pedales', '/imagenes/productos/PE005.jpg'),
('PE006', 'Ibanez TS9', 'El legendario pedal Overdrive Tube Screamer.', 'Revisión exacta del legendario pedal de Overdrive. Destaca por su icónico empuje en frecuencias medias que hace resaltar a la guitarra eléctrica en cualquier mezcla de banda.', 'Circuito: Analógico legendario JRC4558D||Controles: Drive, Tone, Level||Uso: Overdrive principal o Booster para amplificadores a tubos', 99990, 'Pedales', '/imagenes/productos/PE006.jpg'),
('AC001', 'Ernie Ball Super Slinky', 'Cuerdas Guitarra Eléctrica 09-42. Níquel entorchado.', 'Las cuerdas de guitarra eléctrica más populares del mundo. Fabricadas con alambre de acero niquelado envuelto alrededor de un núcleo de acero hexagonal.', 'Calibres: .009, .011, .016, .024w, .032, .042||Material: Acero niquelado||Origen: Hecho en Coachella, EE.UU.', 8990, 'Accesorios', '/imagenes/productos/AC001.jpg'),
('AC002', 'Ernie Ball Earthwood', 'Cuerdas Guitarra Acústica 12-53. Bronce 80/20.', 'Cuerdas para guitarra acústica de bronce 80/20 que brindan un sonido claro, brillante y lleno de armónicos resonantes.', 'Calibres: .012, .016, .024w, .032, .044, .053||Composición: 80% Cobre, 20% Zinc', 10990, 'Accesorios', '/imagenes/productos/AC002.jpg'),
('AC003', 'Ernie Ball Regular Slinky', 'Cuerdas Bajo 45-105. Entorchado redondo.', 'Cuerdas para bajo de 4 cuerdas de la serie Slinky Bass. Entregan agudos definidos y graves profundos con máxima durabilidad.', 'Calibres: .045, .065, .080, .105||Tipo: Roundwound (Entorchado redondo)', 14990, 'Accesorios', '/imagenes/productos/AC003.jpg'),
('AC004', 'Fender 351 (x12)', 'Púas de Guitarra x12 (0.73mm) de celuloide.', 'Pack de 12 uñetas Fender tradicionales de celuloide. Proporcionan un ataque suave y una flexibilidad media ideal para rasgueos.', 'Grosor: Medium (0.73mm)||Cantidad: 12 unidades||Material: Celuloide Premium', 4990, 'Accesorios', '/imagenes/productos/AC004.jpg'),
('AC005', 'Dunlop Trigger', 'Capotraste Guitarra en aluminio de aviación.', 'Capotasto con mecanismo de muelle para cambio rápido con una sola mano. Acolchado protector que no daña el acabado del mástil.', 'Material: Aluminio de grado aeronáutico||Compatibilidad: Guitarras acústicas y eléctricas de diapasón curvo', 12990, 'Accesorios', '/imagenes/productos/AC005.jpg'),
('AC006', 'Snark SN-5', 'Afinador de Clip con pantalla giratoria.', 'Afinador de pinza para pala de guitarra, bajo y violín. Pantalla a color giratoria en 360 grados de lectura ultrarrápida.', 'Sensor: Transductor de vibración de alta frecuencia||Pantalla: LCD a color rotativa 360°', 8990, 'Accesorios', '/imagenes/productos/AC006.jpg'),
('AC007', 'Monster S100-I-3', 'Cable Instrumento 3m blindado.', 'Cable profesional de 3 metros para instrumento con conectores Plug de 1/4" rectos y blindaje trenzado para rechazo absoluto de ruidos e interferencias.', 'Largo: 3 Metros (10 ft)||Conectores: Jack 1/4" Mono a Jack 1/4" Mono||Blindaje: 90% cobre trenzado', 12990, 'Accesorios', '/imagenes/productos/AC007.jpg'),
('AC008', 'Monster S100-I-6', 'Cable Instrumento 6m blindado.', 'Versión de 6 metros del afamado cable Monster S100, diseñado para músicos de escenario que requieren movilidad libre sin degradar la señal de audio.', 'Largo: 6 Metros (20 ft)||Conectores: Jack 1/4" metálicos de alta durabilidad', 17990, 'Accesorios', '/imagenes/productos/AC008.jpg'),
('AC009', 'Hercules GS302B', 'Soporte Guitarra de Piso plegable.', 'Soporte de piso compacto para guitarra eléctrica o bajo. Su diseño ultra liviano permite plegarlo plano para transportarlo en cualquier funda.', 'Capacidad: 1 instrumento (Eléctrica/Bajo)||Acolchado: Espuma de formulación especial (SFF) segura para acabados delicados', 22990, 'Accesorios', '/imagenes/productos/AC009.jpg'),
('AC010', 'Hercules WAH-202', 'Soporte Guitarra de Pared base madera.', 'Soporte de pared colgante con sistema Auto-Swivel y base de madera maciza para exhibir tus instrumentos de forma elegante y segura.', 'Sistema: Auto-Grip (AGS) que bloquea el instrumento automáticamente al colgarlo||Base: Madera noble barnizada', 18990, 'Accesorios', '/imagenes/productos/AC010.jpg'),
